.error { color: red; margin-top: 12px; }
</style>
</head>
<body ng-controller="ServerTableCtrl">
<table ng-if="students.length">
<caption>Student List (From PHP)</caption>
<thead>
<tr><th>#</th><th>Name</th><th>Age</th><th>Course</th></tr>
</thead>
<tbody>
<tr ng-repeat="s in students track by $index">
<td>{{ $index + 1 }}</td>
<td>{{ s.name }}</td>
<td>{{ s.age }}</td>
<td>{{ s.course }}</td>
</tr>
</tbody>
</table>
<div class="loading" ng-if="loading">Loading data from server...</div>
<div class="error" ng-if="error">{{ error }}</div>
<script>
angular.module('tableAppServer', [])
.controller('ServerTableCtrl', function($scope, $http) {
$scope.students = [];
$scope.loading = true;
$scope.error = null;
// Adjust path if PHP file is in a different folder
$http.get('students.php')
.then(function(response){
$scope.students = response.data;
$scope.loading = false;
})
.catch(function(err){
$scope.error = 'Failed to load data. Check students.php and server.';
$scope.loading = false;
console.error(err);
});
});
</script>
</body>
</html>

